import heapq


def strange_sort_list(lst):
    if not lst:
        return []

    min_heap = []
    max_heap = []

    for num in lst:
        if len(min_heap) == len(max_heap):
            heapq.heappush(max_heap, -num)
        else:
            heapq.heappush(min_heap, num)

        if max_heap and min_heap:
            if max_heap[0] > min_heap[0]:
                max_heap.pop(0)
                min_heap.append(heapq.heappop(max_heap))
                min_heap.append(heapq.heappop(min_heap))
            else:
                min_heap.append(heapq.heappop(min_heap))

    return min_heap + max_heap

