import collections


def histogram(test):
    """
    Given a string representing a space separated lowercase letters, returns a dictionary
    mapping the letter with the most repetition (or any letter in case of a tie) to the corresponding count.

    :param test: str
    :return: dict

    Examples:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """

    if not test:
        return {}

    letter_counts = collections.Counter(test.split())
    max_occurrence = max(letter_counts.values())

    result = {letter: count for letter, count in letter_counts.items() if count == max_occurrence}

    return result

