def words_in_sentence(sentence):
    """
    You are given a string representing a sentence, which contains some words separated by spaces,
    and you have to return a string containing the words from the original sentence, whose lengths
    are prime numbers, in the same order as they appear in the original sentence.
    """
    primes_and_words = []
    for word in sentence.split():
        if is_prime(len(word)):
            primes_and_words.append(word)
